"""Differential driver: candidate entry vs the naive reference model."""
import json, os, subprocess, sys, pathlib
sys.path.insert(0, '/workspace/dev')
import ref

CAND = '/workspace/submission/main.py'
ENV = dict(os.environ, PYTHONDONTWRITEBYTECODE='1')

def candidate_out(data):
    p = subprocess.run([sys.executable, '-B', CAND], input=data.encode(), stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, env=ENV)
    if p.returncode != 0:
        raise RuntimeError('candidate exit %d: %s' % (p.returncode, p.stderr[:400]))
    return p.stdout.decode()

def deep_same(a, b, path=''):
    if type(a) is not type(b):
        # allow int/float normalisation only for ints
        if isinstance(a, int) and isinstance(b, int):
            pass
        else:
            return '%s: type %s vs %s' % (path, type(a), type(b))
    if isinstance(a, dict):
        if set(a) != set(b):
            return '%s: keyset' % path
        for k in a:
            r = deep_same(a[k], b[k], path + '/' + str(k))
            if r: return r
        return None
    if isinstance(a, list):
        if len(a) != len(b):
            return '%s: len %d vs %d' % (path, len(a), len(b))
        for i, (x, y) in enumerate(zip(a, b)):
            r = deep_same(x, y, '%s[%d]' % (path, i))
            if r: return r
        return None
    if a != b:
        return '%s: %r vs %r' % (path, a, b)
    return None

def check_request(request, raw=None, label=''):
    data = raw if raw is not None else json.dumps(request, separators=(',', ':'))
    expect = ref.run_json(data)
    got = candidate_out(data)
    try:
        gotj = json.loads(got)
        expj = json.loads(expect)
    except ValueError as exc:
        print('MISMATCH(%s) parse: %r vs %r' % (label, got[:200], expect[:200]))
        return False
    diff = deep_same(expj, gotj)
    if diff:
        print('MISMATCH(%s) %s' % (label, diff))
        e = json.dumps(expj)[:4000]; g = json.dumps(gotj)[:4000]
        for i, (x, y) in enumerate(zip(e, g)):
            if x != y:
                print('  at char', i, e[max(0,i-100):i+150], '||', g[max(0,i-100):i+150])
                break
        return False
    return True

if __name__ == '__main__':
    fixtures = json.load(open('/workspace/examples/checks.json'))
    ok = True
    for i, f in enumerate(fixtures):
        if 'raw' in f:
            data = f['raw']
            expect = json.dumps(f['response'], separators=(',', ':'))
            got = candidate_out(data)
            same = deep_same(json.loads(expect), json.loads(got))
            print('fixture %d raw: %s' % (i, 'OK' if same is None else same))
            ok = ok and same is None
        else:
            r = check_request(f['request'], label='fixture %d' % i)
            print('fixture %d: %s' % (i, 'OK' if r else 'FAIL'))
            ok = ok and r
    print('ALL OK' if ok else 'FAILURES')
